#include <oauth/GoogleDriveBackupClient.hpp>
#include <OBSApp.hpp>
#include <QCoreApplication>
#include "facts.hpp"
#include <iostream>
using namespace std;
int main(int argc,char**argv){QCoreApplication app(argc,argv);ResetFacts();qunsetenv("OBS_GOOGLE_DRIVE_CLIENT_ID");if(argc>1&&string(argv[1])=="--null-config"){configUnavailable=true;auto registration=GoogleDriveBackupClient::Registration();cout<<"{\"returned\":true,\"empty_fallback\":"<<(registration.clientId.empty()?"true":"false")<<"}\n";return registration.clientId.empty()?0:1;}int checks=0,failures=0;auto check=[&](bool ok,const char*n){++checks;if(!ok){++failures;cerr<<"FAIL "<<n<<'\n';}};config_set_string(App()->GetUserConfig(),"GoogleDriveBackup","ClientId","qa-configured");check(GoogleDriveBackupClient::Registration().clientId=="qa-configured","configured registration retains precedence when available");qputenv("OBS_GOOGLE_DRIVE_CLIENT_ID","qa-environment");check(GoogleDriveBackupClient::Registration().clientId=="qa-environment","environment registration retains precedence");qunsetenv("OBS_GOOGLE_DRIVE_CLIENT_ID");configUnavailable=true;check(GoogleDriveBackupClient::Registration().clientId.empty(),"missing config safely retains configured build fallback semantics");configUnavailable=false;appUnavailable=true;check(GoogleDriveBackupClient::Registration().clientId.empty(),"missing App safely retains configured build fallback semantics");qputenv("OBS_GOOGLE_DRIVE_CLIENT_ID","qa-environment");check(GoogleDriveBackupClient::Registration().clientId=="qa-environment","environment registration works without App");qunsetenv("OBS_GOOGLE_DRIVE_CLIENT_ID");appUnavailable=false;check(ioOnGui==0&&configOnWorker==0,"registration entry uses GUI config and never keyring IO");cout<<"{\"checks\":"<<checks<<",\"failures\":"<<failures<<",\"passed\":"<<(failures?"false":"true")<<"}\n";return failures?1:0;}
